import { createReadStream } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { createServer, type Server, type ServerResponse } from "node:http";

export type ReplyFormat = "markdown" | "plain";
export type AgentType = "codex" | "pi";
export interface CommandKeywordsConfig {
  pause: string[];
  monitorOpen: string[];
  monitorStop: string[];
  switchPi: string[];
  switchCodex: string[];
}

export interface MonitorTarget { groupId: string; groupName: string; senderId: string; senderName: string; }
export interface DashboardConfig { privateChatEnabled: boolean; cardUpdateIntervalMs: number; showElapsed: boolean; historyGroupLimit: number; historyMessageLimit: number; historyPollIntervalSeconds: number; targets: MonitorTarget[]; botAllowedUserIds: string[]; botAllowedUserNames?: Record<string, string>; botSuperAdminUserIds: string[]; botSuperAdminUserNames?: Record<string, string>; robotSenderOpenDingTalkId?: string; commandKeywords: CommandKeywordsConfig; groupPromptPrefix: string; replyFormat: ReplyFormat; robotName: string; clientId: string; clientSecret: string; agent: AgentType; }
interface PublicDashboardConfig extends Omit<DashboardConfig, "clientSecret"> { clientSecretConfigured: boolean; }
export interface ConversationMessage { senderName: string; senderId: string; content: string; createdAt?: string; }
export interface ReplyRecord { id: string; createdAt: string; conversationType: "group" | "personal"; conversationName?: string; groupId: string; groupName: string; status: "processing" | "completed" | "failed"; agent?: AgentType; question?: string; senderNames?: string[]; senderDetails?: ConversationMessage[]; content: string; messageCount: number; }
export interface DashboardStatus { startedAt: string; eventConnected: boolean; lastEventAt?: string; activeBatches: number; }
export interface GroupMatch { groupId: string; groupName: string; memberCount?: number; }
export interface GroupMember { senderId: string; senderName: string; role?: string; }
export interface UserMatch { senderId: string; senderName: string; department?: string; }
export interface BotMatch { openDingTalkId: string; name: string; }
export interface CurrentDwsUser { userId?: string; openDingTalkId?: string; name?: string; email?: string; dept?: string; org?: string; auth?: Record<string, unknown>; }

export interface DashboardHooks {
  getConfig: () => DashboardConfig;
  updateConfig: (config: DashboardConfig) => Promise<void>;
  getStatus: () => DashboardStatus;
  getReplies: () => ReplyRecord[];
  searchGroups: (query: string) => Promise<GroupMatch[]>;
  listGroupMembers: (groupId: string) => Promise<GroupMember[]>;
  searchUsers: (query: string) => Promise<UserMatch[]>;
  searchBots?: (query: string) => Promise<BotMatch[]>;
  getCurrentDwsUser?: () => Promise<CurrentDwsUser>;
  getDwsAuthStatus?: () => Promise<Record<string, unknown>>;
  startDwsDeviceLogin?: () => { started: boolean; message: string };
  getDwsDeviceLoginOutput?: () => Promise<{ running: boolean; output: string }>;
  logoutDws?: () => Promise<void>;
  getBotStatus?: () => Promise<{ enabled: boolean; connected: boolean; updatedAt?: string }>;
}

export interface DashboardServerOptions {
  host?: string;
}

function sendJson(response: ServerResponse, status: number, value: unknown): void {
  response.writeHead(status, { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" });
  response.end(JSON.stringify(value));
}

function publicConfig(config: DashboardConfig): PublicDashboardConfig {
  const { clientSecret, ...rest } = config;
  return { ...rest, clientSecretConfigured: Boolean(clientSecret) };
}

function normalizeConfig(value: unknown): DashboardConfig {
  if (!value || typeof value !== "object") throw new Error("配置必须是 JSON 对象");
  const source = value as { privateChatEnabled?: unknown; cardUpdateIntervalMs?: unknown; showElapsed?: unknown; historyGroupLimit?: unknown; historyMessageLimit?: unknown; historyPollIntervalSeconds?: unknown; targets?: unknown; botAllowedUserIds?: unknown; botAllowedUserNames?: unknown; botSuperAdminUserIds?: unknown; botSuperAdminUserNames?: unknown; robotSenderOpenDingTalkId?: unknown; commandKeywords?: unknown; groupPromptPrefix?: unknown; replyFormat?: unknown; robotName?: unknown; clientId?: unknown; clientSecret?: unknown; robotCode?: unknown; agent?: unknown };
  if (source.privateChatEnabled !== undefined && typeof source.privateChatEnabled !== "boolean") throw new Error("个人私聊开关格式无效");
  if (source.cardUpdateIntervalMs !== undefined && (!Number.isFinite(source.cardUpdateIntervalMs) || Number(source.cardUpdateIntervalMs) <= 0)) throw new Error("卡片更新间隔必须大于 0");
  const cardUpdateIntervalMs = source.cardUpdateIntervalMs === undefined
    ? 3_000
    : Number(source.cardUpdateIntervalMs) <= 60
      ? Number(source.cardUpdateIntervalMs) * 1_000
      : Number(source.cardUpdateIntervalMs);
  if (cardUpdateIntervalMs < 500 || cardUpdateIntervalMs > 60_000) throw new Error("卡片更新间隔需在 0.5-60 秒之间");
  if (source.showElapsed !== undefined && typeof source.showElapsed !== "boolean") throw new Error("总耗时显示开关格式无效");
  const positiveInteger = (value: unknown, fallback: number, name: string) => { const n = value === undefined ? fallback : Number(value); if (!Number.isInteger(n) || n < 1 || n > 500) throw new Error(`${name}需为 1-500 的整数`); return n; };
  const historyGroupLimit = positiveInteger(source.historyGroupLimit, 10, "历史群数量");
  const historyMessageLimit = positiveInteger(source.historyMessageLimit, 20, "历史消息数量");
  const historyPollIntervalSeconds = source.historyPollIntervalSeconds === undefined ? 5 : Number(source.historyPollIntervalSeconds);
  if (!Number.isFinite(historyPollIntervalSeconds) || historyPollIntervalSeconds < 0 || historyPollIntervalSeconds > 3600) throw new Error("历史消息拉取间隔需为 0-3600 秒");
  if (!Array.isArray(source.targets)) throw new Error("钉钉规则格式无效");
  const keys = new Set<string>();
  const targets = source.targets.map((item, index) => {
    if (!item || typeof item !== "object") throw new Error(`第 ${index + 1} 条钉钉规则无效`);
    const candidate = item as Partial<MonitorTarget>;
    const target: MonitorTarget = {
      groupId: candidate.groupId?.trim() ?? "", groupName: candidate.groupName?.trim() ?? "",
      senderId: candidate.senderId?.trim() ?? "", senderName: candidate.senderName?.trim() ?? "",
    };
    if (!target.groupId || !target.groupName || !target.senderId || !target.senderName) {
      throw new Error(`第 ${index + 1} 条规则的群或人员信息不完整`);
    }
    const key = `${target.groupId}:${target.senderId}`;
    if (keys.has(key)) throw new Error(`第 ${index + 1} 条规则重复`);
    keys.add(key);
    return target;
  });
  if (source.replyFormat !== "markdown" && source.replyFormat !== "plain") throw new Error("回复格式只能是 markdown 或 plain");
  if (source.agent !== "codex" && source.agent !== "pi") throw new Error("Agent 只能是 Codex CLI 或 Pi Agent");
  if (!Array.isArray(source.botAllowedUserIds)) throw new Error("请至少配置一名机器人单聊授权人员");
  const botAllowedUserIds = [...new Set(source.botAllowedUserIds.filter((id): id is string => typeof id === "string").map((id) => id.trim()).filter(Boolean))];
  if (botAllowedUserIds.length === 0) throw new Error("请至少配置一名机器人单聊授权人员");
  if (typeof source.robotName !== "string" || !source.robotName.trim()) throw new Error("请填写机器人名称");
  if (typeof source.clientId !== "string" || !source.clientId.trim()) throw new Error("请填写钉钉应用 Client ID");
  if (typeof source.clientSecret !== "string") throw new Error("Client Secret 格式无效");
  const botAllowedUserNames = source.botAllowedUserNames && typeof source.botAllowedUserNames === "object"
    ? Object.fromEntries(Object.entries(source.botAllowedUserNames).filter((entry): entry is [string, string] => typeof entry[0] === "string" && typeof entry[1] === "string"))
    : {};
  const botSuperAdminUserIds = Array.isArray(source.botSuperAdminUserIds)
    ? [...new Set(source.botSuperAdminUserIds.filter((id): id is string => typeof id === "string").map((id) => id.trim()).filter(Boolean))]
    : [];
  if (botSuperAdminUserIds.some((id) => !botAllowedUserIds.includes(id))) throw new Error("Session 超级管理员必须同时是机器人单聊授权人员");
  const botSuperAdminUserNames = source.botSuperAdminUserNames && typeof source.botSuperAdminUserNames === "object"
    ? Object.fromEntries(Object.entries(source.botSuperAdminUserNames).filter((entry): entry is [string, string] => typeof entry[0] === "string" && typeof entry[1] === "string"))
    : {};
  if (!source.commandKeywords || typeof source.commandKeywords !== "object") throw new Error("请配置消息指令关键词");
  const commandSource = source.commandKeywords as Record<string, unknown>;
  const keywordList = (key: string): string[] => {
    if (!Array.isArray(commandSource[key])) throw new Error(`指令关键词 ${key} 格式无效`);
    const values = [...new Set(commandSource[key].filter((item): item is string => typeof item === "string").map((item) => item.trim()).filter(Boolean))];
    return values;
  };
  const commandKeywords: CommandKeywordsConfig = {
    pause: keywordList("pause"), monitorOpen: keywordList("monitorOpen"), monitorStop: keywordList("monitorStop"),
    switchPi: keywordList("switchPi"), switchCodex: keywordList("switchCodex"),
  };
  if (typeof source.groupPromptPrefix !== "string") throw new Error("消息前缀格式无效");
  return { privateChatEnabled: source.privateChatEnabled !== false, cardUpdateIntervalMs, showElapsed: source.showElapsed !== false, historyGroupLimit, historyMessageLimit, historyPollIntervalSeconds, targets, botAllowedUserIds, botAllowedUserNames, botSuperAdminUserIds, botSuperAdminUserNames, robotSenderOpenDingTalkId: typeof source.robotSenderOpenDingTalkId === "string" ? source.robotSenderOpenDingTalkId.trim() : "", commandKeywords, groupPromptPrefix: source.groupPromptPrefix.trim(), replyFormat: source.replyFormat, robotName: source.robotName.trim(), clientId: source.clientId.trim(), clientSecret: source.clientSecret.trim(), agent: source.agent };
}

export function startDashboard(port: number, hooks: DashboardHooks, options: DashboardServerOptions = {}): Server {
  const host = options.host?.trim() || "127.0.0.1";
  const server = createServer((request, response) => {
    const url = new URL(request.url ?? "/", "http://127.0.0.1");
    if (request.method === "GET" && url.pathname === "/favicon.ico") {
      response.writeHead(200, { "content-type": "image/x-icon", "cache-control": "public, max-age=86400" });
      createReadStream(join(dirname(fileURLToPath(import.meta.url)), "..", "outputs", "favicon", "favicon.ico")).pipe(response);
      return;
    }
    if (request.method === "GET" && url.pathname === "/assets/favicon-32.png") {
      response.writeHead(200, { "content-type": "image/png", "cache-control": "public, max-age=86400" });
      createReadStream(join(dirname(fileURLToPath(import.meta.url)), "..", "outputs", "favicon", "favicon-32.png")).pipe(response);
      return;
    }
    if (request.method === "GET" && url.pathname === "/assets/omi-icon.png") {
      response.writeHead(200, { "content-type": "image/png", "cache-control": "public, max-age=86400" });
      createReadStream(join(dirname(fileURLToPath(import.meta.url)), "..", "outputs", "omi-icon.png")).pipe(response);
      return;
    }
    if (request.method === "GET" && url.pathname === "/") {
      response.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
      response.end(PAGE);
      return;
    }
    if (request.method === "GET" && url.pathname === "/favicon.ico") {
      response.writeHead(204, { "cache-control": "public, max-age=86400" });
      response.end();
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/state") {
      sendJson(response, 200, { config: publicConfig(hooks.getConfig()), status: hooks.getStatus(), replies: hooks.getReplies().slice(0, 10) });
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/users") {
      const query = url.searchParams.get("q")?.trim() ?? "";
      if (!query) return sendJson(response, 400, { error: "请输入钉钉人名" });
      void hooks.searchUsers(query).then((users) => sendJson(response, 200, { users })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
      if (request.method === "GET" && url.pathname === "/api/bot-status") {
      if (!hooks.getBotStatus) return sendJson(response, 501, { error: "机器人状态查询不可用" });
      void hooks.getBotStatus().then((status) => sendJson(response, 200, { status })).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/dws-auth-status") {
      if (!hooks.getDwsAuthStatus) return sendJson(response, 501, { error: "DWS 认证状态查询不可用" });
      void hooks.getDwsAuthStatus().then((status) => sendJson(response, 200, { status })).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/dws-device-login") {
      if (!hooks.startDwsDeviceLogin) return sendJson(response, 501, { error: "DWS Device Flow 不可用" });
      return sendJson(response, 200, hooks.startDwsDeviceLogin());
    }
    if (request.method === "GET" && url.pathname === "/api/dws-device-login") {
      if (!hooks.getDwsDeviceLoginOutput) return sendJson(response, 501, { error: "DWS Device Flow 不可用" });
      void hooks.getDwsDeviceLoginOutput().then((result) => sendJson(response, 200, result)).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/dws-logout") {
      if (!hooks.logoutDws) return sendJson(response, 501, { error: "DWS 退出登录不可用" });
      void hooks.logoutDws().then(() => sendJson(response, 200, { loggedOut: true })).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/current-user") {
      if (!hooks.getCurrentDwsUser) return sendJson(response, 501, { error: "当前 DWS 登录账号查询不可用" });
      void hooks.getCurrentDwsUser().then((user) => sendJson(response, 200, { user })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/bots") {
      const query = url.searchParams.get("q")?.trim() ?? "";
      if (!query) return sendJson(response, 400, { error: "请输入机器人名称" });
      if (!hooks.searchBots) return sendJson(response, 501, { error: "机器人搜索功能不可用" });
      void hooks.searchBots(query).then((bots) => sendJson(response, 200, { bots })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/groups") {
      const query = url.searchParams.get("q")?.trim() ?? "";
      if (!query) return sendJson(response, 400, { error: "请输入群名称" });
      void hooks.searchGroups(query).then((groups) => sendJson(response, 200, { groups })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    const membersMatch = url.pathname.match(/^\/api\/groups\/([^/]+)\/members$/);
    if (request.method === "GET" && membersMatch) {
      void hooks.listGroupMembers(decodeURIComponent(membersMatch[1])).then((members) => sendJson(response, 200, { members })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    if (request.method === "PUT" && url.pathname === "/api/config") {
      let body = "";
      request.setEncoding("utf8");
      request.on("data", (chunk: string) => { body += chunk; });
      request.on("end", () => {
        try {
          if (body.length > 100_000) throw new Error("请求内容过大");
          const config = normalizeConfig(JSON.parse(body));
          if (!config.clientSecret) config.clientSecret = hooks.getConfig().clientSecret;
          console.log(`[Dashboard] saving config agent=${config.agent} targets=${config.targets.length} botUsers=${config.botAllowedUserIds.length}`);
          if (!config.clientSecret) throw new Error("请填写钉钉应用 Client Secret");
          void hooks.updateConfig(config).then(() => {
            console.log(`[Dashboard] config saved agent=${config.agent} targets=${config.targets.length}`);
            sendJson(response, 200, { config: publicConfig(config), saved: true });
          }).catch((err) => {
            console.error(`[Dashboard] config save failed: ${err instanceof Error ? err.message : String(err)}`);
            sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) });
          });
        } catch (err) {
          sendJson(response, 400, { error: err instanceof Error ? err.message : String(err) });
        }
      });
      return;
    }
    sendJson(response, 404, { error: "Not found" });
  });
  server.listen(port, host);
  return server;
}

